package main

import("encoding/base64";"fmt";"strconv";"strings")
// A bounded vector renderer avoids a font/image-cache process. Same 256px black,
// red-count and dark outlined zero/question states; no background animation.
type Artwork struct{}
func loadArt(root string)(*Artwork,error){return &Artwork{},nil}
func viewKey(count *int64)string{if count==nil{return "?"};return strconv.FormatInt(*count,10)}
func(a *Artwork)render(count *int64)([]byte,error){text:=viewKey(count);if count!=nil&&*count<0{text="?"};fill,stroke:="url(#red)","#fd7575";if text=="0"||text=="?"{fill="url(#dark)";stroke="#b9bdc3"};size:=112;if len(text)>2{size=210/len(text)+18};if size<17{size=17};var out strings.Builder;fmt.Fprintf(&out,`<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256" viewBox="0 0 256 256"><defs><linearGradient id="frame" x2="0" y2="1"><stop stop-color="#64686d"/><stop offset="0.18" stop-color="#17191c"/><stop offset="0.8" stop-color="#070809"/><stop offset="1" stop-color="#34383c"/></linearGradient><linearGradient id="red" x2="0" y2="1"><stop stop-color="#ff6264"/><stop offset="0.46" stop-color="#e22730"/><stop offset="1" stop-color="#86070c"/></linearGradient><linearGradient id="dark" x2="0" y2="1"><stop stop-color="#24272c"/><stop offset="1" stop-color="#030405"/></linearGradient></defs><rect width="256" height="256" fill="#000"/><rect x="6" y="6" width="244" height="244" rx="26" fill="url(#frame)" stroke="#767b82" stroke-width="1.2"/><rect x="13" y="13" width="230" height="230" rx="21" fill="#050608" stroke="#212429"/><path d="M31 21H225" stroke="#979ba1" opacity=".42"/><text x="128" y="45" text-anchor="middle" font-family="Segoe UI,Arial,sans-serif" font-size="20" font-weight="700" letter-spacing="2" fill="#f4f4f5">NICKNACKS</text><text x="128" y="163" text-anchor="middle" font-family="Segoe UI,Arial,sans-serif" font-size="%d" font-weight="800" fill="%s" stroke="%s" stroke-width="1.4" paint-order="stroke">%s</text><g transform="translate(93 202)" fill="none" stroke="#c2c5cb" stroke-width="1.5"><path d="M0 4L9 0L18 4V16L9 20L0 16Z M0 4L9 8L18 4 M9 8V20 M5 2L14 6"/></g><text x="128" y="191" text-anchor="middle" font-family="Segoe UI,Arial,sans-serif" font-size="13" font-weight="600" letter-spacing="2" fill="#d6d8dc">PROCESSING</text><path d="M35 233H221" stroke="#4a4d53" opacity=".6"/></svg>`,size,fill,stroke,text);return []byte(out.String()),nil}
func imageURI(b []byte)string{return "data:image/svg+xml;base64,"+base64.StdEncoding.EncodeToString(b)}
